const float ANIM_LENGTH_SEC = 3.0;
const float MASK_ALPHA = 0.5;
const float STAGE_1_START = 0.1;
const float STAGE_2_START = 0.4;
const float STAGE_3_START = 0.6;
const float STAGE_4_START = 0.7;
const vec3 MASK = vec3(1.);
const vec3 SPRITE_BACKGROUND = vec3(1., 0., 0.);
const vec3 BACKGROUND = vec3(0.0);
const float BEAM_HEIGHT = 0.1;
const vec3 BEAM_COLOR = vec3(.8, .8, 1.);
const float STAGE_4_ALPHA_LEVEL = -acos(MASK_ALPHA);

void mainImage( out vec4 fragColor, in vec2 fragCoord)
{
    float timePerc = mod(iTime, ANIM_LENGTH_SEC) / ANIM_LENGTH_SEC;
    vec2 uv = fragCoord / iResolution.xy;
    vec4 texColor = texture(iChannel0, uv);
    float alpha = texColor.a;
    float colorPerc = 1.;
    vec3 color = texColor.rgb;
    float glitch = mod(timePerc * 100., 1.0);
    vec4 random = texture(iChannel1, vec2(uv.x + glitch, uv.y - glitch));

    if (timePerc <= STAGE_1_START) {
        // Fade in the sprite background
        timePerc = timePerc / STAGE_1_START;

        alpha = clamp(texColor.a, 0.0, timePerc);
        alpha = clamp(random.x, 0.0, alpha);
        color = SPRITE_BACKGROUND;
    }
    else if (timePerc <= STAGE_2_START) {
        timePerc = (timePerc - STAGE_1_START) / (STAGE_2_START - STAGE_1_START);
        color = SPRITE_BACKGROUND;
        alpha = clamp(random.x, 0.0, alpha);
    }
    else if (timePerc <= STAGE_3_START) {
        // Travel from top to bottom

        timePerc = 1. - ((timePerc - STAGE_2_START)/ (STAGE_3_START - STAGE_2_START));
        colorPerc = clamp((uv.y - timePerc) * 2., 0.0, 1. - MASK_ALPHA);

        float aberration = exp(-50. * pow(uv.y - timePerc, 2.)) * sin(timePerc * 3.14 / 2.) * 0.1;

        texColor = texture(iChannel0, vec2(uv.x + aberration, uv.y));
        alpha = texColor.a;
        color = texColor.rgb;
        if (uv.y >= timePerc) {
            color = colorPerc * texColor.rgb + (1. - colorPerc) * MASK;
        } else if (uv.y >= timePerc - BEAM_HEIGHT) {
            color = BEAM_COLOR;
        } else {
            color = SPRITE_BACKGROUND;
            alpha = clamp(random.x, 0.0, alpha);
        }
    } else if (timePerc <= STAGE_4_START) {
        timePerc = ((timePerc - STAGE_3_START)/ (STAGE_4_START - STAGE_3_START));
        float mask_prog = (1. - timePerc) * STAGE_4_ALPHA_LEVEL + timePerc * 1.57;
        mask_prog = cos(mask_prog);
        color = (1. - mask_prog) * texColor.rgb +  mask_prog * MASK;
    }

    vec3 pixelColor = alpha * color + (1. - alpha) * BACKGROUND;
    fragColor = vec4(pixelColor, 1.0);
}

